import 'dart:convert';import 'package:flutter/foundation.dart';import 'package:hive/hive.dart';/// On-device AI Assistant — offline survival intelligence./// TFLite-based for medical triage, field identification, first aid, navigation.class AIAssistantService {  static const String _chatBox = 'catus_ai_chat';  Box<String>? _box;  // Pre-loaded knowledge base (embedded survival data)  final Map<String, String> _survivalKB = {    'cpr': 'CPR Steps: 1) Check responsiveness 2) Call for help 3) Open airway (head tilt, chin lift) 4) Check breathing 5) 30 chest compressions at 2 inches deep, rate 100-120/min 6) 2 rescue breaths 7) Repeat 30:2 cycle until help arrives or AED available.',    'bleeding': 'Severe Bleeding: 1) Apply direct pressure with clean cloth 2) Elevate injured area above heart 3) Apply tourniquet if bleeding doesn\'t stop (limbs only) — mark time applied 4) Do NOT remove initial bandage, add on top 5) Get to medical care ASAP.',    'fracture': 'Fracture Management: 1) Do NOT move unless in danger 2) Immobilize joint above and below break 3) Apply splint (sticks, rolled magazine, etc.) 4) Check pulse below injury frequently 5) Ice if available (20 min on, 20 off) 6) Monitor for shock.',    'water': 'Water Purification: 1) BOILING: Rolling boil for 1 min (3 min above 6500ft) 2) CHEMICAL: 2 drops bleach per quart, wait 30 min 3) FILTER: Use cloth + sand + charcoal layers 4) UV: Clear bottle in direct sunlight 6+ hours 5) NEVER drink seawater.',    'fire': 'Fire Starting: 1) Gather tinder (dry leaves, bark), kindling (twigs), fuel (logs) 2) Build fire lay: teepee or log cabin 3) Methods: friction (bow drill), flint/steel, battery+steel wool, lens 4) Protect from wind 5) Never leave unattended.',    'shelter': 'Emergency Shelter: 1) Location: high ground, near water, windbreak 2) Types: lean-to, debris hut, snow cave 3) Insulation: leaves, grass, pine needles underneath 4) Size: small to retain heat 5) Entrance away from wind 6) Signal nearby.',    'snakebite': 'Snakebite: 1) Stay calm, minimize movement 2) Remove jewelry near bite 3) Immobilize limb at or below heart level 4) DO NOT cut, suck, or tourniquet 5) Mark edge of swelling with pen + time 6) Get to hospital — take photo of snake if safe.',    'navigation': 'Navigation Without GPS: 1) SUN: Rises East, sets West 2) STARS: North Star (Polaris) in Northern hemisphere, Southern Cross in Southern 3) STICK: Plant stick, mark shadow tip, wait 15 min, mark again — line points East-West 4) MOSS: Generally grows on North side (unreliable).',    'signaling': 'Rescue Signaling: 1) MIRROR: Flash at aircraft/rescuers 2) THREE fires in triangle 3) SOS: ··· ——— ··· (3 short, 3 long, 3 short) 4) Ground signals: X = need help, V = need assistance 5) WHISTLE: 3 blasts = distress 6) Bright colored items visible.',    'hypothermia': 'Hypothermia: 1) Move to warm sheltered area 2) Remove wet clothing 3) Warm core first (armpits, groin, neck) 4) Warm sweet drinks (NOT alcohol) 5) Body-to-body contact in sleeping bag 6) Do NOT rub extremities or put in hot water 7) Handle gently.',  };  Future<void> initialize() async {    _box = await Hive.openBox<String>(_chatBox);  }  /// Ask the AI assistant a survival question  AIChatResponse ask(String question) {    final q = question.toLowerCase();    // Search knowledge base    for (final entry in _survivalKB.entries) {      if (q.contains(entry.key) || _fuzzyMatch(q, entry.key)) {        final response = AIChatResponse(          answer: entry.value,          confidence: 0.95,          source: 'Offline survival knowledge base',          category: _categorize(entry.key),        );        _saveToHistory(question, response);        return response;      }    }    // Broader keyword matching    final keywords = {      'hurt': 'bleeding', 'wound': 'bleeding', 'cut': 'bleeding',      'broken': 'fracture', 'bone': 'fracture',      'cold': 'hypothermia', 'freeze': 'hypothermia',      'drink': 'water', 'thirsty': 'water', 'dehydrat': 'water',      'lost': 'navigation', 'direction': 'navigation', 'compass': 'navigation',      'help': 'signaling', 'rescue': 'signaling',      'snake': 'snakebite', 'bite': 'snakebite',      'warm': 'fire', 'cook': 'fire',      'sleep': 'shelter', 'rain': 'shelter', 'camp': 'shelter',      'breath': 'cpr', 'heart': 'cpr', 'unconscious': 'cpr',    };    for (final entry in keywords.entries) {      if (q.contains(entry.key)) {        final kbKey = entry.value;        if (_survivalKB.containsKey(kbKey)) {          final response = AIChatResponse(            answer: _survivalKB[kbKey]!,            confidence: 0.8,            source: 'Offline survival knowledge base (fuzzy match)',            category: _categorize(kbKey),          );          _saveToHistory(question, response);          return response;        }      }    }    return AIChatResponse(      answer: 'I don\'t have a specific answer for that in my offline knowledge base. '          'Available topics: CPR, bleeding, fractures, water purification, fire starting, '          'shelter building, snakebites, navigation, signaling, and hypothermia. '          'Try asking about one of these topics.',      confidence: 0.2,      source: 'No match found',      category: 'general',    );  }  /// Medical triage — symptom assessment  TriageResult triage(List<String> symptoms) {    int score = 0;    String priority = 'GREEN';    final actions = <String>[];    final criticalSymptoms = ['unconscious', 'not breathing', 'severe bleeding', 'chest pain', 'seizure'];    final urgentSymptoms = ['broken bone', 'deep cut', 'burn', 'head injury', 'difficulty breathing'];    final moderateSymptoms = ['pain', 'swelling', 'nausea', 'dizziness', 'fever'];    for (final s in symptoms) {      final sl = s.toLowerCase();      if (criticalSymptoms.any((c) => sl.contains(c))) {        score += 3;        actions.add('IMMEDIATE: Address $s — see first aid protocol');      } else if (urgentSymptoms.any((u) => sl.contains(u))) {        score += 2;        actions.add('URGENT: Treat $s within 1 hour');      } else if (moderateSymptoms.any((m) => sl.contains(m))) {        score += 1;        actions.add('MONITOR: Track $s symptoms');      }    }    if (score >= 5) priority = 'RED';    else if (score >= 3) priority = 'YELLOW';    return TriageResult(score: score, priority: priority, actions: actions);  }  bool _fuzzyMatch(String query, String keyword) {    return query.split(' ').any((word) =>        word.length > 3 && keyword.contains(word.substring(0, 3)));  }  String _categorize(String key) {    const medicalKeys = ['cpr', 'bleeding', 'fracture', 'snakebite', 'hypothermia'];    const survivalKeys = ['water', 'fire', 'shelter', 'navigation', 'signaling'];    if (medicalKeys.contains(key)) return 'medical';    if (survivalKeys.contains(key)) return 'survival';    return 'general';  }  void _saveToHistory(String question, AIChatResponse response) {    final entry = {      'question': question,      'answer': response.answer,      'timestamp': DateTime.now().toIso8601String(),    };    _box?.add(jsonEncode(entry));  }}class AIChatResponse {  final String answer, source, category;  final double confidence;  AIChatResponse({required this.answer, required this.confidence,    required this.source, required this.category});}class TriageResult {  final int score;  final String priority;  final List<String> actions;  TriageResult({required this.score, required this.priority, required this.actions});}